import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { attendanceService } from '../../services/attendanceService';

// --- Utils ---
const statusMap = {
  'Present': { text: 'Có mặt', color: '#10b981', bg: '#dcfce7' },
  'Absent': { text: 'Vắng mặt', color: '#ef4444', bg: '#fee2e2' },
  'Leave': { text: 'Nghỉ phép', color: '#f59e0b', bg: '#fef3c7' }
};

const getStatusInfo = (status) => statusMap[status] || { text: status, color: '#64748b', bg: '#f1f5f9' };

const getInitials = (name) => {
  if (!name) return 'NV';
  return name.split(' ').map((w) => w[0]).slice(-2).join('').toUpperCase();
};

// --- Main Component ---
export default function AttendanceList(props) {
  const { onNavigateReport, onNavigateWorkAnniversary, selectedMonth: propsMonth, setSelectedMonth: propsSetMonth, availableMonths: propsAvailableMonths, selectedDate: propsDate, setSelectedDate: propsSetDate, attendanceRows: propsRows, isLoading: propsLoading } = props;

  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState(propsMonth || '2024-09');
  const [selectedDate, setSelectedDate] = useState(propsDate || new Date().toISOString().split('T')[0]);
  const [selectedDept, setSelectedDept] = useState('ALL');

  const [summaryData, setSummaryData] = useState([]);
  const [todayData, setTodayData] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [todayPage, setTodayPage] = useState(1);

  const availableMonths = propsAvailableMonths || [
    { value: '2024-09', label: 'Tháng 9, 2024' },
    { value: '2026-05', label: 'Tháng 5, 2026' }
  ];

  useEffect(() => {
    fetchSummary();
  }, [selectedMonth]);

  useEffect(() => {
    fetchToday();
  }, [selectedDate]);

  const fetchSummary = async () => {
    setIsLoading(true);
    try {
      const res = await attendanceService.getSummary(selectedMonth);
      if (res.success) setSummaryData(res.data || []);
    } catch (e) { console.error(e); }
    setIsLoading(false);
  };

  const fetchToday = async () => {
    try {
      const res = await attendanceService.getTodayAttendance(selectedDate);
      if (res.success) setTodayData(res.data || []);
    } catch (e) { console.error(e); }
  };

  const depts = useMemo(() => Array.from(new Set(summaryData.map(d => d.DepartmentName).filter(Boolean))), [summaryData]);
  const filteredSummary = useMemo(() => selectedDept === 'ALL' ? summaryData : summaryData.filter(d => d.DepartmentName === selectedDept), [summaryData, selectedDept]);

  const pagedRows = filteredSummary.slice((currentPage - 1) * 10, currentPage * 10);
  const pagedToday = todayData.slice((todayPage - 1) * 5, todayPage * 5);

  const stats = {
    present: summaryData.filter(r => r.PresentDays > 0).length,
    absent: summaryData.filter(r => r.AbsentDays > 0).length,
    leave: summaryData.filter(r => r.LeaveDays > 0).length
  };

  return (
    <div className="premium-dashboard" style={{ padding: '30px', backgroundColor: '#f4f7fa', minHeight: '100vh', fontFamily: "'Outfit', sans-serif" }}>

      {/* ── Top Action Bar ── */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '32px' }}>
        <div style={{ position: 'relative', flex: 1, maxWidth: '500px' }}>
          <span style={{ position: 'absolute', left: '16px', top: '50%', transform: 'translateY(-50%)', fontSize: '18px', color: '#94a3b8' }}>🔍</span>
          <input 
            type="text" 
            placeholder="Tìm kiếm nhân viên, mã số..." 
            style={{ width: '100%', padding: '14px 20px 14px 48px', borderRadius: '16px', border: 'none', backgroundColor: '#fff', boxShadow: '0 4px 12px rgba(0,0,0,0.03)', outline: 'none', fontSize: '15px' }}
          />
        </div>
        <div style={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
          <select 
            value={selectedMonth}
            onChange={(e) => { setSelectedMonth(e.target.value); if(propsSetMonth) propsSetMonth(e.target.value); }}
            style={{ padding: '12px 20px', borderRadius: '14px', border: 'none', backgroundColor: '#fff', fontWeight: '700', color: '#1e293b', boxShadow: '0 4px 12px rgba(0,0,0,0.03)', cursor: 'pointer' }}
          >
            {availableMonths.map(m => <option key={m.value} value={m.value}>{m.label}</option>)}
          </select>
          <button 
            onClick={onNavigateWorkAnniversary}
            style={{ padding: '12px 24px', borderRadius: '14px', border: 'none', backgroundColor: '#6366f1', color: '#fff', fontWeight: '700', cursor: 'pointer', boxShadow: '0 10px 15px -3px rgba(99,102,241,0.3)' }}
          >
            🎗️ Thông báo kỷ niệm
          </button>
        </div>
      </div>

      {/* ── Stats Grid ── */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '24px', marginBottom: '32px' }}>
        {[
          { label: 'Tổng nhân viên', value: summaryData.length, icon: '👥', color: '#4f46e5', bg: '#e0e7ff' },
          { label: 'Có mặt tháng này', value: stats.present, icon: '✨', color: '#10b981', bg: '#dcfce7' },
          { label: 'Có vắng mặt', value: stats.absent, icon: '🛑', color: '#ef4444', bg: '#fee2e2' },
          { label: 'Có nghỉ phép', value: stats.leave, icon: '🏖️', color: '#f59e0b', bg: '#fef3c7' }
        ].map((item, idx) => (
          <div key={idx} style={{ backgroundColor: '#fff', padding: '24px', borderRadius: '24px', boxShadow: '0 10px 20px -5px rgba(0,0,0,0.03)', display: 'flex', flexDirection: 'column', gap: '12px', border: '1px solid rgba(255,255,255,0.8)' }}>
            <div style={{ width: '44px', height: '44px', borderRadius: '14px', backgroundColor: item.bg, color: item.color, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '20px' }}>
              {item.icon}
            </div>
            <div>
              <div style={{ color: '#94a3b8', fontSize: '14px', fontWeight: '600', textTransform: 'uppercase', letterSpacing: '0.5px' }}>{item.label}</div>
              <div style={{ fontSize: '32px', fontWeight: '800', color: '#1e293b' }}>{item.value}</div>
            </div>
          </div>
        ))}
      </div>

      {/* ── Main Content Table ── */}
      <div style={{ backgroundColor: '#fff', borderRadius: '28px', padding: '30px', boxShadow: '0 4px 25px rgba(0,0,0,0.02)', marginBottom: '32px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
          <div>
            <h3 style={{ margin: 0, fontSize: '20px', fontWeight: '800', color: '#1e293b' }}>Nhật ký chấm công</h3>
            <p style={{ margin: '4px 0 0 0', color: '#94a3b8', fontSize: '13px' }}>Danh sách nhân viên và tình trạng đi làm trong tháng</p>
          </div>
          <select 
            value={selectedDept}
            onChange={(e) => setSelectedDept(e.target.value)}
            style={{ padding: '10px 16px', borderRadius: '12px', border: '1px solid #e2e8f0', color: '#64748b', fontWeight: '600' }}
          >
            <option value="ALL">Tất cả phòng ban</option>
            {depts.map(d => <option key={d} value={d}>{d}</option>)}
          </select>
        </div>

        <table style={{ width: '100%', borderCollapse: 'separate', borderSpacing: '0 10px' }}>
          <thead>
            <tr>
              <th style={{ textAlign: 'left', padding: '0 16px', color: '#94a3b8', fontSize: '12px', fontWeight: '700', textTransform: 'uppercase' }}>NHÂN VIÊN</th>
              <th style={{ textAlign: 'left', padding: '0 16px', color: '#94a3b8', fontSize: '12px', fontWeight: '700', textTransform: 'uppercase' }}>MÃ SỐ</th>
              <th style={{ textAlign: 'left', padding: '0 16px', color: '#94a3b8', fontSize: '12px', fontWeight: '700', textTransform: 'uppercase' }}>PHÒNG BAN</th>
              <th style={{ textAlign: 'left', padding: '0 16px', color: '#94a3b8', fontSize: '12px', fontWeight: '700', textTransform: 'uppercase' }}>TÌNH TRẠNG</th>
              <th style={{ textAlign: 'center', padding: '0 16px', color: '#94a3b8', fontSize: '12px', fontWeight: '700', textTransform: 'uppercase' }}>HÀNH ĐỘNG</th>
            </tr>
          </thead>
          <tbody>
            {pagedRows.map((row) => (
              <tr key={row.EmployeeID}>
                <td style={{ backgroundColor: '#fcfdfe', padding: '16px', borderTopLeftRadius: '16px', borderBottomLeftRadius: '16px', border: '1px solid #f1f5f9', borderRight: 'none' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '14px' }}>
                    <div style={{ width: '40px', height: '40px', borderRadius: '12px', backgroundColor: '#6366f115', color: '#6366f1', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: '700' }}>
                      {getInitials(row.FullName)}
                    </div>
                    <div>
                      <div style={{ fontWeight: '700', color: '#1e293b' }}>{row.FullName}</div>
                      <div style={{ fontSize: '12px', color: '#94a3b8' }}>{row.Email || '-'}</div>
                    </div>
                  </div>
                </td>
                <td style={{ backgroundColor: '#fcfdfe', padding: '16px', borderTop: '1px solid #f1f5f9', borderBottom: '1px solid #f1f5f9', color: '#64748b', fontWeight: '600' }}>EMP-{String(row.EmployeeID).padStart(5, '0')}</td>
                <td style={{ backgroundColor: '#fcfdfe', padding: '16px', borderTop: '1px solid #f1f5f9', borderBottom: '1px solid #f1f5f9', color: '#1e293b', fontWeight: '600' }}>{row.DepartmentName || '-'}</td>
                <td style={{ backgroundColor: '#fcfdfe', padding: '16px', borderTop: '1px solid #f1f5f9', borderBottom: '1px solid #f1f5f9' }}>
                  <span style={{ 
                    padding: '6px 14px', borderRadius: '10px', fontSize: '12px', fontWeight: '800', 
                    backgroundColor: row.PresentDays > 0 ? '#dcfce7' : row.AbsentDays > 0 ? '#fee2e2' : '#fef3c7',
                    color: row.PresentDays > 0 ? '#10b981' : row.AbsentDays > 0 ? '#ef4444' : '#f59e0b'
                  }}>
                    {row.PresentDays > 0 ? 'Có mặt' : row.AbsentDays > 0 ? 'Vắng mặt' : 'Nghỉ phép'}
                  </span>
                </td>
                <td style={{ backgroundColor: '#fcfdfe', padding: '16px', borderTopRightRadius: '16px', borderBottomRightRadius: '16px', border: '1px solid #f1f5f9', borderLeft: 'none', textAlign: 'center' }}>
                  <button style={{ background: '#fff', border: '1px solid #e2e8f0', padding: '6px 12px', borderRadius: '8px', color: '#64748b', fontSize: '13px', cursor: 'pointer', fontWeight: '600' }}>Chi tiết</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* ── Today & Calendar Section ── */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.5fr', gap: '30px' }}>
        <div style={{ backgroundColor: '#fff', borderRadius: '28px', padding: '24px', boxShadow: '0 4px 25px rgba(0,0,0,0.02)' }}>
          <h3 style={{ margin: '0 0 20px 0', fontSize: '18px', fontWeight: '800', color: '#1e293b' }}>Lịch chấm công</h3>
          <div style={{ textAlign: 'center', marginBottom: '20px', fontWeight: '700', color: '#3b82f6' }}>{availableMonths.find(m => m.value === selectedMonth)?.label}</div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '10px', textAlign: 'center' }}>
            {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map(d => <span key={d} style={{ fontSize: '12px', color: '#94a3b8', fontWeight: '700' }}>{d}</span>)}
            {Array.from({ length: 31 }, (_, i) => (
              <div 
                key={i} 
                onClick={() => setSelectedDate(`${selectedMonth}-${String(i+1).padStart(2, '0')}`)}
                style={{ 
                  padding: '10px 0', borderRadius: '12px', cursor: 'pointer', fontSize: '14px', fontWeight: '600',
                  backgroundColor: selectedDate.endsWith(String(i+1).padStart(2, '0')) ? '#3b82f6' : 'transparent',
                  color: selectedDate.endsWith(String(i+1).padStart(2, '0')) ? '#fff' : '#475569'
                }}
              >
                {i + 1}
              </div>
            ))}
          </div>
        </div>

        <div style={{ backgroundColor: '#fff', borderRadius: '28px', padding: '24px', boxShadow: '0 4px 25px rgba(0,0,0,0.02)', display: 'flex', flexDirection: 'column' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
            <h3 style={{ margin: 0, fontSize: '18px', fontWeight: '800', color: '#1e293b' }}>Chấm công ngày {selectedDate.split('-').reverse().join('/')}</h3>
            <button 
              onClick={onNavigateReport}
              style={{ padding: '8px 16px', borderRadius: '10px', backgroundColor: '#f1f5f9', border: 'none', color: '#1e293b', fontWeight: '700', cursor: 'pointer', fontSize: '13px' }}
            >
              📊 Xem báo cáo chi tiết
            </button>
          </div>
          <div style={{ flex: 1 }}>
            {pagedToday.length === 0 ? (
              <div style={{ padding: '40px', textAlign: 'center', color: '#94a3b8' }}>Không có dữ liệu ngày này</div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                {pagedToday.map((item, idx) => (
                  <div key={idx} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 16px', backgroundColor: '#fcfdfe', borderRadius: '16px', border: '1px solid #f1f5f9' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                      <div style={{ width: '32px', height: '32px', borderRadius: '8px', backgroundColor: '#3b82f615', color: '#3b82f6', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: '700', fontSize: '12px' }}>{item.FullName.charAt(0)}</div>
                      <span style={{ fontWeight: '700', color: '#1e293b', fontSize: '14px' }}>{item.FullName}</span>
                    </div>
                    <span style={{ fontSize: '12px', color: '#64748b' }}>{item.PhoneNumber}</span>
                    <span style={{ 
                      padding: '4px 10px', borderRadius: '8px', fontSize: '11px', fontWeight: '800', 
                      backgroundColor: getStatusInfo(item.Status).bg, color: getStatusInfo(item.Status).color 
                    }}>{getStatusInfo(item.Status).text}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
          <div style={{ marginTop: '20px', textAlign: 'right' }}>
            <button style={{ background: 'none', border: 'none', color: '#3b82f6', fontWeight: '700', cursor: 'pointer' }}>Xem thêm ➜</button>
          </div>
        </div>
      </div>

    </div>
  );
}
